// Mock PayPal adapter, backed by fixtures/paypal/*.json (generated by scripts/generate-fixtures.ts
// from lib/seed). It behaves like the sandbox where it matters to SetAside: it rejects Transaction
// Search ranges over 31 days, pages results, hides anything newer than three hours before the demo
// clock (PayPal's documented lag), and reports balances as of the clock.

import fs from 'node:fs';
import path from 'node:path';
import type { Currency } from '../money';
import { toDecimalString } from '../money';
import {
  PayPalError,
  TRANSACTION_SEARCH_MAX_DAYS,
  type InvoiceDraft,
  type InvoiceResult,
  type PayPalAdapter,
  type PayPalInvoice,
  type PayPalSearchResponse,
  type PayPalTransactionDetail,
} from './types';

export const TRANSACTION_SEARCH_LAG_MS = 3 * 3_600_000;

type Fixture = { transactions: PayPalTransactionDetail[]; invoices: PayPalInvoice[] };
const cache = new Map<Currency, Fixture>();

export function loadFixture(currency: Currency): Fixture {
  let fixture = cache.get(currency);
  if (!fixture) {
    const dir = path.join(process.cwd(), 'fixtures', 'paypal');
    fixture = {
      transactions: JSON.parse(fs.readFileSync(path.join(dir, `transactions-${currency}.json`), 'utf8')).transaction_details,
      invoices: JSON.parse(fs.readFileSync(path.join(dir, `invoices-${currency}.json`), 'utf8')).items,
    };
    cache.set(currency, fixture);
  }
  return fixture;
}

const at = (t: PayPalTransactionDetail) => Date.parse(t.transaction_info.transaction_initiation_date!.replace('+0000', 'Z'));

export class MockPayPal implements PayPalAdapter {
  readonly mode = 'mock' as const;
  constructor(
    private readonly currency: Currency,
    private readonly now: () => Date,
  ) {}

  async searchTransactions({ start, end, page, pageSize }: { start: Date; end: Date; page: number; pageSize: number }): Promise<PayPalSearchResponse> {
    if (end.getTime() - start.getTime() > TRANSACTION_SEARCH_MAX_DAYS * 86_400_000) {
      throw new PayPalError(400, 'GET /v1/reporting/transactions', '{"name":"INVALID_REQUEST","message":"Date range is greater than 31 days"}');
    }
    const refreshed = this.now().getTime() - TRANSACTION_SEARCH_LAG_MS;
    const all = loadFixture(this.currency).transactions.filter((t) => {
      const ts = at(t);
      return ts >= start.getTime() && ts <= end.getTime() && ts <= refreshed;
    });
    const totalPages = Math.max(1, Math.ceil(all.length / pageSize));
    return {
      transaction_details: all.slice((page - 1) * pageSize, page * pageSize),
      account_number: 'SETASIDEDEMO1',
      start_date: start.toISOString(),
      end_date: end.toISOString(),
      last_refreshed_datetime: new Date(refreshed).toISOString(),
      page,
      total_items: all.length,
      total_pages: totalPages,
    };
  }

  async getBalances() {
    const now = this.now().getTime();
    const seen = loadFixture(this.currency).transactions.filter((t) => at(t) <= now);
    const last = seen.at(-1)?.transaction_info.ending_balance ?? { currency_code: this.currency, value: '0.00' };
    return {
      balances: [{ currency: this.currency, primary: true, total_balance: last, available_balance: last, withheld_balance: { currency_code: this.currency, value: '0.00' } }],
      account_id: 'SETASIDEDEMO1',
      as_of_time: this.now().toISOString(),
      last_refresh_time: this.now().toISOString(),
    };
  }

  async listInvoices() {
    const today = this.now().toISOString().slice(0, 10);
    return loadFixture(this.currency).invoices.filter((i) => (i.detail.invoice_date ?? '') <= today);
  }

  async createPaidInvoice(draft: InvoiceDraft): Promise<InvoiceResult> {
    const id = `INV2-MOCK-${draft.paidByTransactionId.slice(0, 8)}`;
    const value = toDecimalString(draft.amountMinor);
    const money = { currency_code: draft.currency, value };
    const invoice: PayPalInvoice = {
      id,
      status: 'MARKED_AS_PAID',
      detail: {
        invoice_number: `SA-${draft.paidByTransactionId.slice(-6)}`,
        currency_code: draft.currency,
        invoice_date: draft.invoiceDate,
        reference: draft.paidByTransactionId,
        note: draft.note,
        payment_term: { term_type: 'DUE_ON_RECEIPT' },
        metadata: { recipient_view_url: `https://www.sandbox.paypal.com/invoice/p/#${id}`, create_time: this.now().toISOString() },
      },
      primary_recipients: [{ billing_info: { business_name: draft.recipientName, email_address: draft.recipientEmail } }],
      items: [{ name: draft.itemName, quantity: '1', unit_amount: money }],
      amount: money,
      due_amount: { currency_code: draft.currency, value: '0.00' },
      payments: { paid_amount: money, transactions: [{ payment_date: draft.paymentDate, method: 'PAYPAL', note: `PayPal transaction ${draft.paidByTransactionId}`, amount: money }] },
    };
    return {
      invoice,
      steps: [
        { call: 'POST /v2/invoicing/invoices', ok: true, detail: `${id} (mock)` },
        { call: `POST /v2/invoicing/invoices/${id}/payments`, ok: true, detail: 'recorded as paid (mock)' },
      ],
    };
  }
}
